python - <<'PY'
import json,numpy as np
from PIL import Image
for folder in ['initial','step_07']:
 rgb=np.array(Image.open(f'/app/output/captures/{folder}/head_camera.jpg'));d=np.load(f'/app/output/captures/{folder}/head_camera_depth.npy')[0].astype(float)
 m=json.load(open(f'/app/output/captures/{folder}/meta.json'))['cameras']['head_camera'];K=np.array(m['intrinsic_cv']);E=np.array(m['extrinsic_cv']);R=E[:,:3];t=E[:,3]
 H,W=d.shape; yy,xx=np.indices((H,W));
 # material mask red-ish pixels; for placement spatial region around current cup in image
 mask=(rgb[:,:,0].astype(int)-rgb[:,:,1]>25)&(rgb[:,:,1].astype(int)-rgb[:,:,2]>5)
 if folder=='initial': mask &= (xx>280)&(yy<140)
 else: mask &= (xx>210)&(xx<270)&(yy<130)
 ys,xs=np.where(mask); pts=[]
 for u,v in zip(xs,ys):
  z=d[v,u]/1000; pc=np.array([(u-160)*z/K[0,0],(v-120)*z/K[1,1],z]);pts.append(R.T@(pc-t))
 a=np.array(pts)
 print(folder,'n',len(xs),'pix', (xs.min(),xs.max(),ys.min(),ys.max()))
 for band in [(0,85),(85,95),(95,110),(110,140),(140,240)]:
  q=(ys>=band[0])&(ys<band[1])
  if q.any(): print(band,'median',np.median(a[q],axis=0).round(3),'zspan',a[q,2].min().round(3),a[q,2].max().round(3))
PY

